def rpc(msg_id, method, params=None):
    return {"jsonrpc": "2.0", "id": msg_id, "method": method,
            "params": params if params is not None else {}}

def unwrap(resp):
    if "error" in resp:
        return (None, resp["error"])
    return (resp.get("result"), None)

