def validate_acs(acs):
    parts = ("given", "when", "then")
    broken = []
    for idx, ac in enumerate(acs):
        low = ac.lower()
        if not all(p in low for p in parts):
            broken.append(idx)
    return {"total": len(acs), "complete": len(acs) - len(broken), "broken": broken}

