            for i, item in enumerate(acc, 1):
                if not isinstance(item, str) or not item:
                    problems.append(f"acceptance 第 {i} 条必须为非空字符串")
    if "forbidden" in card and not isinstance(card["forbidden"], list):
        problems.append("forbidden 必须是列表")
    return problems

