def calibrate(records):
    stats = {}
    for ttype, ok in records:
        s = stats.setdefault(ttype, [0, 0])
        s[0] += 1
        s[1] += 1 if ok else 0
    out = {}
    for ttype, (n, ok_n) in stats.items():
        rate = ok_n / n
        if rate >= 0.9:
            level = 3
        elif rate >= 0.7:
            level = 2
        elif rate >= 0.5:
            level = 1
        else:
            level = 0
        out[ttype] = {"rate": round(rate, 2), "level": level, "note": "" if n >= 5 else "样本不足"}
    return out

