BLOCK_WORDS = ("请立即", "执行", "脚本", "访问 http", "https://")

def sanitize(text):
    """防线 1: 进入前消毒 -- 疑似注入载荷不进入 Agent 上下文"""
    hits = [w for w in BLOCK_WORDS if w in text]
    if "http" in text and len(hits) >= 2:
        return "[载荷已拦截: 疑似指令注入, 原文隔离待人工审查]", hits
    return text, []

